tests:
package exercise

import (
	"bytes"
	"io"
	"os"
	"testing"
)

func TestGreet(t *testing.T) {
	buffer := bytes.Buffer{}
	Greet(&buffer, "Chris")

	got := buffer.String()
	want := "Hello, Chris"
	if got != want {
		t.Errorf("Greet wrote %q, want %q", got, want)
	}
}

func TestGreetToStdout(t *testing.T) {
	old := os.Stdout
	r, w, _ := os.Pipe()
	os.Stdout = w
	defer func() { os.Stdout = old }()

	GreetToStdout("Elodie")
	w.Close()

	out, _ := io.ReadAll(r)
	got := string(out)
	want := "Hello, Elodie"
	if got != want {
		t.Errorf("GreetToStdout printed %q, want %q", got, want)
	}
}

solution:
package exercise

import (
	"fmt"
	"io"
	"os"
)

func Greet(writer io.Writer, name string) {
	fmt.Fprintf(writer, "Hello, %s", name)
}

func GreetToStdout(name string) {
	Greet(os.Stdout, name)
}

